def _insert_simple(table: str, rows: list[tuple]) -> None:
    has_description = len(rows[0]) == 3
    columns = ["code", "name", "sort_order"] + (["description"] if has_description else [])
    tbl = sa.table(table, *(sa.column(c) for c in columns))
    op.bulk_insert(tbl, [
        dict(zip(columns, (row[0], row[1], (i + 1) * 10) + ((row[2],) if has_description else ())))
        for i, row in enumerate(rows)
    ])


