    _insert_simple("scale_or_cut_options", SCALE_OR_CUT_OPTIONS)

    conn = op.get_bind()
    conn.execute(
        sa.text("""
            INSERT INTO goals (code, name, funnel_stage_id, sort_order)
            SELECT g.code, g.name, fs.id, g.sort_order
            FROM unnest(CAST(:codes AS text[]), CAST(:names AS text[]), CAST(:stages AS text[]), CAST(:orders AS int[]))
                 AS g(code, name, stage_code, sort_order)
            JOIN funnel_stages fs ON fs.code = g.stage_code
        """),
        {
            "codes": [g[0] for g in GOALS],
            "names": [g[1] for g in GOALS],
            "stages": [g[2] for g in GOALS],
            "orders": [(i + 1) * 10 for i in range(len(GOALS))],
        },
    )

    pairs = [(ch, sub) for ch, subs in CHANNEL_SUB_CHANNELS.items() for sub in subs + ["OTHER"]]
    conn.execute(
        sa.text("""
            INSERT INTO channel_sub_channels (channel_id, sub_channel_id)
            SELECT c.id, s.id
            FROM unnest(CAST(:channels AS text[]), CAST(:subs AS text[])) AS p(channel_code, sub_code)
            JOIN channels c ON c.code = p.channel_code
            JOIN sub_channels s ON s.code = p.sub_code
        """),
        {"channels": [p[0] for p in pairs], "subs": [p[1] for p in pairs]},
    )


